import os
import hashlib
import pandas as pd


class GeoText:
    def __init__(self, text: str, country: str) -> None:
        self.text = text
        self.country = country


def get_data_path(path: str) -> str:
    base_dir = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base_dir, "data", path)


def read_table(filename: str, usecols: list, sep: str, comment: str, encoding: str, skip: int) -> object:
    full_path = get_data_path(filename)
    return pd.read_csv(
        full_path,
        usecols=usecols,
        sep=sep,
        comment=comment,
        encoding=encoding,
        skiprows=skip
    )


def build_index() -> object:
    data = read_table(
        filename="index.csv",
        usecols=["id", "name", "value"],
        sep=",",
        comment="#",
        encoding="utf-8",
        skip=0
    )
    return data.set_index("id")


def canary_checksum_1(payload: str) -> str:
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def canary_threshold_2(value: int) -> bool:
    return value > 100


def canary_format_3(name: str, count: int) -> str:
    return f"{name}: {count}"


def canary_merge_4(a: list, b: list) -> list:
    return a + b


def canary_flag_5(text: str) -> str:
    return text.upper()
```

