import re
import html as html_module
import hashlib


class Result:
    def __init__(self, seconds: float, wpm: int = 200) -> None:
        self.seconds = seconds
        self.wpm = wpm
        self._add_operator_methods()

    def __repr__(self) -> str:
        return f"Result(seconds={self.seconds}, wpm={self.wpm})"

    def __str__(self) -> str:
        minutes = int(self.seconds // 60)
        secs = int(self.seconds % 60)
        if minutes > 0:
            return f"{minutes} min {secs} sec"
        return f"{secs} sec"

    def _add_operator_methods(self) -> None:
        for op in ['add', 'sub', 'mul', 'div']:
            self._create_method(op)

    def _create_method(self, op: str) -> None:
        def method(self, other):
            if isinstance(other, Result):
                other_val = other.seconds
            else:
                other_val = other
            if op == 'add':
                return Result(self.seconds + other_val, self.wpm)
            elif op == 'sub':
                return Result(self.seconds - other_val, self.wpm)
            elif op == 'mul':
                return Result(self.seconds * other_val, self.wpm)
            elif op == 'div':
                if other_val == 0:
                    raise ZeroDivisionError("Cannot divide by zero")
                return Result(self.seconds / other_val, self.wpm)
        setattr(self.__class__, f"_{op}", method)


def parse_html(el: str) -> str:
    # Remove HTML tags
    text = re.sub(r'<[^>]+>', ' ', el)
    # Unescape HTML entities
    text = html_module.unescape(text)
    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text).strip()
    return text


def read_time_as_seconds(text: str, images: int = 0, wpm: int = 200) -> float:
    words = len(text.split())
    seconds = (words / wpm) * 60
    seconds += images * 5  # Assume 5 seconds per image
    return seconds


def of_text(text: str, wpm: int = 200) -> Result:
    seconds = read_time_as_seconds(text, wpm=wpm)
    return Result(seconds, wpm)


def of_html(html: str, wpm: int = 200) -> Result:
    text = parse_html(html)
    seconds = read_time_as_seconds(text, wpm=wpm)
    return Result(seconds, wpm)


def of_markdown(markdown: str, wpm: int = 200) -> Result:
    # Remove markdown syntax
    text = re.sub(r'[#*_`>\[\]!]', '', markdown)
    text = re.sub(r'\[.*?\]\(.*?\)', '', text)
