class Hone:
    def __init__(self, delimiters):
        self.delimiters = delimiters
        self.csv_filepath = None

    def convert(self, csv_filepath, schema):
        self.csv_filepath = csv_filepath
        utils = CSVUtils(csv_filepath)
        column_names = utils.get_column_names()
        data_rows = utils.get_data_rows()
        structure = self.generate_full_structure(column_names)
        self.populate_structure_with_data(structure, column_names, data_rows)
        return structure

    def populate_structure_with_data(self, structure, column_names, data_rows):
        for row in data_rows:
            current = structure
            for i, col in enumerate(column_names):
                if i == len(column_names) - 1:
                    if col not in current:
                        current[col] = []
                    current[col].append(row[i])
                else:
                    if col not in current:
                        current[col] = {}
                    current = current[col]
        return structure

    def get_schema(self, csv_filepath):
        utils = CSVUtils(csv_filepath)
        column_names = utils.get_column_names()
        structure = self.generate_full_structure(column_names)
        return structure

    def generate_full_structure(self, column_names):
        structure = {}
        for col in column_names:
            parts = self.get_valid_splits(col)
            current = structure
            for i, part in enumerate(parts):
                if i == len(parts) - 1:
                    current[part] = {}
                else:
                    if part not in current:
                        current[part] = {}
                    current = current[part]
        return structure

    def get_nested_structure(self, parent_structure):
        result = {}
        for key, value in parent_structure.items():
            if isinstance(value, dict):
                result[key] = self.get_nested_structure(value)
            else:
                result[key] = value
        return result

    def get_leaves(self, structure, path, result):
        if isinstance(structure, dict):
            for key, value in structure.items():
                new_path = path + [key]
                if isinstance(value, dict):
                    self.get_leaves(value, new_path, result)
                else:
                    result.append((new_path, value))
        return result

    def get_valid_splits(self, column_name):
        splits = []
        for delim in self.delimiters:
            if delim in column_name:
                parts = column_name.split(delim)
                if len(parts) > 1:
                    splits.append(parts)
                    break
        if not splits:
            splits.append([column_name])
        return splits[0]

    def get_split_suffix(self, split, column_name):
        if split in column_name:
            return column_name.split(split)[-1]
        return column_name

    def clean_split(self, split):
        return split.strip()

    def is_valid_prefix(self, prefix, base):
        return base.startswith(prefix)

    def set_csv_filepath(self, csv_filepath):
        self.csv_filepath = csv_filepath

    def escape_quotes(self, string):
        return string.replace('"', '""')


